{
  "ops": [
    {
      "op": "form",
      "props": {
        "Caption": "Settings",
        "Width": 4800,
        "Height": 2805,
        "MaxButton": false,
        "MinButton": false
      }
    },
    {
      "op": "add",
      "type": "TabStrip",
      "name": "TabStrip1",
      "props": {
        "Left": 240,
        "Top": 240,
        "Width": 4320,
        "Height": 480,
        "Tabs": "General\nAdvanced"
      }
    },
    {
      "op": "add",
      "type": "Frame",
      "name": "Frame1",
      "props": {
        "Caption": "General",
        "Width": 4320,
        "Height": 840
      },
      "place": {
        "below": "TabStrip1",
        "gap": 120
      }
    },
    {
      "op": "add",
      "type": "Frame",
      "name": "Frame2",
      "props": {
        "Caption": "Advanced",
        "Width": 4320,
        "Height": 840,
        "Visible": false
      },
      "place": {
        "below": "TabStrip1",
        "gap": 120
      }
    },
    {
      "op": "add",
      "type": "CheckBox",
      "name": "chkGeneral",
      "container": "Frame1",
      "props": {
        "Caption": "Enable notifications",
        "Left": 240,
        "Top": 360,
        "Width": 3840,
        "Height": 315
      }
    },
    {
      "op": "add",
      "type": "CheckBox",
      "name": "chkAdvanced",
      "container": "Frame2",
      "props": {
        "Caption": "Enable advanced logging",
        "Left": 240,
        "Top": 360,
        "Width": 3840,
        "Height": 315
      }
    },
    {
      "op": "autosize",
      "names": [
        "chkGeneral",
        "chkAdvanced"
      ]
    },
    {
      "op": "add",
      "type": "CommandButton",
      "name": "cmdOK",
      "props": {
        "Caption": "OK",
        "Width": 1215,
        "Height": 375
      }
    },
    {
      "op": "add",
      "type": "CommandButton",
      "name": "cmdCancel",
      "props": {
        "Caption": "Cancel",
        "Width": 1215,
        "Height": 375
      }
    },
    {
      "op": "arrange",
      "names": [
        "cmdOK",
        "cmdCancel"
      ],
      "as": "row",
      "left": 2010,
      "top": 1800
    }
  ],
  "code": "Private Sub Form1_Load()\n    Frame1.Visible = True\n    Frame2.Visible = False\nEnd Sub\nPrivate Sub TabStrip1_Click()\n    If TabStrip1.SelectedItem.Caption = \"General\" Then\n        Frame1.Visible = True\n        Frame2.Visible = False\n    Else\n        Frame1.Visible = False\n        Frame2.Visible = True\n    End If\nEnd Sub\nPrivate Sub cmdOK_Click()\n    Unload Me\nEnd Sub\nPrivate Sub cmdCancel_Click()\n    Unload Me\nEnd Sub"
}

